let askQuestion='',askResult=null;
titles.ask=['Ask Minerva','Questions answered from the mapped records, with evidence you can inspect.'];
function askItemHtml(i){
  if(i.comparison_id)return `<article class="panel ask-item"><h3>${esc(i.title)}</h3>${badge(i.status)}<p>${esc(i.text)}</p><p><b>Commonality:</b> ${esc(i.commonality)}</p><p><b>Not established:</b> ${esc(i.not_established)}</p><details><summary>Inspect the comparison and its sources</summary>${i.axes.map(a=>`<p><b>${esc(a.axis)}</b><br><b>${esc(i.subjects[0])}:</b> ${esc(a.left)}<br><b>${esc(i.subjects[1])}:</b> ${esc(a.right)}</p>`).join('')}${i.evidence.map(e=>row(e.standard_id,'Source Receipt · page '+e.pdf_page)).join('')}<p><b>Next evidence:</b> ${esc(i.next_evidence)}</p><button data-ask-comparison="${esc(i.comparison_id)}">Open full comparison</button></details></article>`;
  return `<article class="panel ask-item"><div class="ask-item-head"><h3>${esc(i.title)}</h3>${badge(i.status)}</div><p class="muted">${esc(i.placement)}${i.placement_kind==='band'?' · shared band context':''}</p><p>${esc(i.text)}</p>${i.qualifiers.length?`<ul>${i.qualifiers.map(q=>`<li>${esc(q)}</li>`).join('')}</ul>`:''}<details><summary>What New York said · ${esc(node(i.standard_id).label)}</summary><blockquote>${esc(i.source_quote)}</blockquote>${i.annotations.map(a=>`<h4>${esc(a.kind)}</h4><blockquote>${esc(a.original_text)}</blockquote>`).join('')}</details><div class="ask-receipts">${row(i.standard_id,'Open source Receipt · page '+i.pdf_page)}${i.node_id!==i.standard_id?row(i.node_id,'Open parsed expectation'):''}</div></article>`;
}
function askHtml(){return `<form id="ask-form" class="ask-form"><label for="ask-question">Your question</label><div class="ask-input-row"><input id="ask-question" name="question" type="text" maxlength="500" autocomplete="off" value="${esc(askQuestion)}" placeholder="What expectations have we mapped for Matthew?" aria-describedby="ask-help" required><button type="submit">Ask Minerva</button></div><p id="ask-help" class="muted">This first version understands a bounded set of record questions. Questions stay in this page; they are not sent to another service.</p></form><div class="ask-examples" aria-label="Example questions">${MinervaAnswers.EXAMPLES.map(q=>`<button data-ask-example="${esc(q)}">${esc(q)}</button>`).join('')}</div><section id="ask-answer" class="ask-answer" tabindex="-1" aria-label="Answer">${askResult?`<div class="panel ask-answer-head"><div class="kicker">${esc(askResult.kind==='unanswered'?'CANNOT ANSWER':askResult.kind==='unmapped'?'COVERAGE GAP':'FROM THE MAPPED RECORDS')}</div><h2>${esc(askResult.title)}</h2><p>${esc(askResult.summary)}</p></div>${askResult.items.map(askItemHtml).join('')}<details class="methodology"><summary>Answer scope and limits</summary>${askResult.limits.map(l=>`<p>${esc(l)}</p>`).join('')}<p>Record query: ${esc(askResult.version)}. Educational data: ${esc(askResult.model_release)}. Policy snapshot: ${esc(askResult.policy_snapshot)}. ${release.thursday_audit_status==='pass-with-recorded-limits'?'Thursday’s separate AI review passed the bounded question layer and safeguards after repairs. Fresh rendered QA remains open; review-status presentation has builder checks.':'Wednesday’s audit covers its frozen data; this answer layer awaits Thursday’s separate review.'}</p></details>`:'<p class="muted">Choose an example or ask about mapped expectations, source wording, grade placement or subject comparisons.</p>'}</section>`;}
function submitAsk(question){
  askQuestion=question.trim();closeReceipt(false);
  askResult=MinervaAnswers.answer(askQuestion,{model,manifest,comparisons});
  render();$('#ask-answer').focus();
}
function bindAsk(){
  if(!$('#ask-form'))return;
  $('#ask-form').onsubmit=e=>{e.preventDefault();submitAsk($('#ask-question').value);};
  $('#ask-question').oninput=e=>askQuestion=e.target.value;
  document.querySelectorAll('[data-ask-example]').forEach(b=>b.onclick=()=>submitAsk(b.dataset.askExample));
  document.querySelectorAll('[data-ask-comparison]').forEach(b=>b.onclick=()=>{comparisonStatus='ALL';comparisonSubject='ALL';navigate('crossroads');const card=document.getElementById(b.dataset.askComparison);if(card){card.open=true;card.querySelector('summary').focus();card.scrollIntoView({block:'start'});}});
}
